data: {"index":1,"delta":{"text":" threatening marine life, particularly organisms that build shells and coral reefs.\n\n---\n\n### Effects of Climate Change\nThe consequences","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" of a warming planet are diverse, severe, and increasingly visible, impacting both natural ecosystems and human societies.\n\n*   **","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"Extreme Weather Events:** Climate change has increased the frequency and intensity of extreme weather. Heatwaves are more prolonged, droughts are more severe, and","type":"text"},"event_type":"step.delta"}

